const baseApi=api;api=async function(action,payload={}){if(remote?.parentToken)payload={parentToken:remote.parentToken,familyId:remote.familyId,...payload};return baseApi(action,payload);};
$('modal').querySelector('.modal-close').addEventListener('click',closeModal);$('profile-button').addEventListener('click',()=>window.Notifications?Notifications.open():profiles());window.addEventListener('hashchange',navigate);document.addEventListener('error',e=>{if(e.target?.tagName==='IMG')e.target.hidden=true;},true);window.addEventListener('beforeunload',()=>{battle?.close();Family.leave();Lobby.leave();});navigate();if(remote&&remote.profile.id!=='__parent__')api('state').then(r=>{setProfile(r.profile);render();}).catch(e=>toast('Profil en cache : '+e.message));
async function parentCall(action,payload={}){if(!parent)throw Error('Ouvre l’espace parent.');if(remote){const result=await api(action,payload);if(result.profiles){remote.profile=result.profiles.find(p=>p.id===remote.profile.id)||C.upgrade(C.makeProfile('__parent__','Parent',4,'⚙️'));header();}return result;}if(action==='familyList')return {ok:true,profiles:data.profiles};const index=data.profiles.findIndex(p=>p.id===payload.childId);if(action==='familyCreate'){if(index>=0)throw Error('Identifiant déjà utilisé.');data.profiles.push(C.parentEdit(C.upgrade(C.makeProfile(payload.childId,'Nouvel enfant',4,'🦊')),payload.patch));}else{if(index<0)throw Error('Enfant introuvable.');if(action==='familyUpdate')data.profiles[index]=C.parentEdit(data.profiles[index],payload.patch);if(action==='familyDelete'){if(payload.confirmName!==data.profiles[index].name)throw Error('Recopie le prénom.');data.profiles.splice(index,1);}if(action==='familyKey')throw Error('Les clés ne sont utilisées qu’avec Google Sheets.');}if(!data.profiles.some(p=>p.id===data.active))data.active=data.profiles[0]?.id||'';persist();header();return {ok:true,profiles:data.profiles};}
async function parentConnect(endpoint,key){config.endpoint=endpoint;await api('parentCheck',{player:'__parent__',token:'',parentToken:key});localStorage.setItem('brawl-connection',JSON.stringify(config));remote={profile:C.upgrade(C.makeProfile('__parent__','Parent',4,'⚙️')),token:'',parentToken:key,delegated:true,originalSession:null};parent=true;render();await ParentAccounts.refresh();}
async function connectParentAccount(result){authenticated=true;remote={profile:C.upgrade(C.makeProfile('__parent__','Parent',4,'⚙️')),token:'',parentToken:result.token,familyId:result.familyId,delegated:true,originalSession:null};parent=true;ParentAccounts.clear();sessionStorage.removeItem('brawl-session');localStorage.removeItem('brawl-session');closeModal();go('parent');render();await ParentAccounts.refresh();}
function connectChildAccount(result){authenticated=true;remote={profile:C.upgrade(result.profile),token:result.token};parent=false;ParentAccounts.clear();localStorage.setItem('brawl-session',JSON.stringify(remote));closeModal();goNow('home');}
function startDemo(){authenticated=true;remote=null;parent=false;go('home');render();}
async function restoreChild(){if(!remote?.token||remote.delegated)return;const token=remote.token;try{const result=await api('authChildMe');if(remote?.token!==token)return;connectChildAccount({...result,token});}catch(err){if(remote?.token===token)throw err;}}
function clearAccount(){socialLeave(Family.currentParty()?.peerRoomId||battle?.peerRoomId);Family.leave();battle?.close();DuelLobby.cancel();authenticated=false;remote=null;parent=false;ParentAccounts.clear();sessionStorage.removeItem('brawl-session');localStorage.removeItem('brawl-session');go('login');render();}
function parentSelectChild(p){if(!parent)throw Error('Ouvre l’espace parent.');if(remote){if(!remote.delegated)remote.originalSession=remote.token?{profile:remote.profile,token:remote.token}:null;remote.delegated=true;remote.profile=p;}else{data.active=p.id;persist();}header();}
async function parentOpenChild(p){parentSelectChild(p);go('apartment');}
queueMicrotask(()=>AuthUI.restore());
function socialLeave(roomId){if(!remote?.token||parent)return;const body=JSON.stringify({action:'activityLeave',player:remote.profile.id,token:remote.token,roomId});try{if(!navigator.sendBeacon(config.endpoint,new Blob([body],{type:'text/plain;charset=utf-8'})))throw Error('Envoi différé');}catch{fetch(config.endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body,keepalive:true}).catch(()=>{});}}
